import csv
from datetime import datetime, timedelta

from openpyxl import Workbook


def _shift_time(value):
    """Subtract three hours from a time value.

    Accepts datetime strings, time-only strings (HH:MM[:SS]), or values
    already representing datetime/time objects. Returns the shifted value
    formatted the same way it was received when possible.
    """
    if value is None or value == "":
        return value

    # If it's already a datetime, just shift it.
    if isinstance(value, datetime):
        return value - timedelta(hours=3)

    text = str(value).strip()

    # Try a list of common formats. Order matters: try datetime first, then time.
    datetime_formats = [
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d %H:%M",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%dT%H:%M",
        "%m/%d/%Y %H:%M:%S",
        "%m/%d/%Y %H:%M",
        "%d/%m/%Y %H:%M:%S",
        "%d/%m/%Y %H:%M",
    ]
    for fmt in datetime_formats:
        try:
            dt = datetime.strptime(text, fmt)
            return (dt - timedelta(hours=3)).strftime(fmt)
        except ValueError:
            continue

    time_formats = ["%H:%M:%S", "%H:%M"]
    for fmt in time_formats:
        try:
            dt = datetime.strptime(text, fmt)
            # Use a reference date so subtraction wraps correctly across midnight.
            shifted = dt - timedelta(hours=3)
            return shifted.strftime(fmt)
        except ValueError:
            continue

    # If nothing matched, return the original value unchanged.
    return value


def format(path):
    """Read a CSV, subtract 3 hours from each value in the 4th column,
    and write the result to /workspace/audit-export.xlsx."""
    wb = Workbook()
    ws = wb.active

    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.reader(f)
        for i, row in enumerate(reader):
            # Assume the first row is a header and copy it through unchanged.
            if i > 0 and len(row) >= 4:
                row[3] = _shift_time(row[3])
            ws.append(row)

    wb.save("/workspace/audit-export.xlsx")


if __name__ == "__main__":
    import sys

    if len(sys.argv) > 1:
        format(sys.argv[1])
